#!/bin/bash
# Start the HIVV gateway.
#
# NEVER hardcode a database password here. It reads, in order:
#   1. HIVV_DB_PASSWORD from the environment
#   2. api/.db-password (0600, generated by setup.sh)
# and refuses to start if neither exists — a known default in the repo means
# every clone has an open database.
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")"

if [ -z "${HIVV_DB_PASSWORD:-}" ]; then
    if [ -f .db-password ]; then
        HIVV_DB_PASSWORD="$(cat .db-password)"
    else
        echo "FATAL: no database password." >&2
        echo "  Set it:  export HIVV_DB_PASSWORD=\$(openssl rand -hex 24)" >&2
        echo "  Or run:  ./setup.sh   (generates one into api/.db-password)" >&2
        exit 1
    fi
fi
export HIVV_DB_PASSWORD

exec node server.js
